// ===== 进 AI 之前的本地粗筛（只读标题）=====
// 位置：24h内5 → 【本节点】 → 打标签
// 命中标准：标题里出现规则词（正文不再参与，省 token）
// 命中 → 原样往下送；一个都没命中 → 整条丢弃
const src = $json;

// ↓↓↓ 规则表：一条一行 [正则, 标签名]；与「打标签」节点必须完全一致 ↓↓↓
const 标签规则 = [
  [/深度求索|幻方量化|梁文锋|DeepSeek/i, 'DeepSeek'],
  [/华为|任正非|余承东|鸿蒙|海思|昇腾|HUAWEI|HarmonyOS|HiSilicon/i, '华为'],
  [/苹果|iPhone|iOS|Mac|库克|Apple/i, '苹果'],
  [/人工智能|大模型|ChatGPT|OpenAI|Claude|Gemini|\bAI\b|LLM/i, '人工智能'],
  [/特斯拉|Model [3YXS]|马斯克|Tesla/i, '特斯拉'],
  [/粤语|广府话|广东话|广州话/i, '粤语'],
  [/英语|English|英文|雅思|托福|口语|翻译|双语/i, '英语'],
];
// ↑↑↑ 规则表结束 ↑↑↑

const 标题 = String(src['标题'] || '');

const 命中 = 标签规则.some(([词]) => {
  const g = new RegExp(词.source, 'gi');
  return g.test(标题);
});

if (!命中) return null;

// 洗掉 HTML 与多余空白，压成一行，标题最多 200 字
const 净 = String(标题).replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();

return { json: { ...src, 标题: 净.length > 200 ? 净.slice(0, 200) : 净 } };

// ===== 打本地预标签（只读标题）=====
// 输出：标签（命中几个写几个，用 / 连接）
// 中文标签就在这里转成英文给 AI；AI 之后返回的中文标签会再转回中文。
const src = $json;

// ↓↓↓ 规则表：一条一行 [正则, 中文标签]；与「本地标签筛选」节点必须完全一致 ↓↓↓
const 标签规则 = [
  [/深度求索|幻方量化|梁文锋|DeepSeek/i, 'DeepSeek'],
  [/华为|任正非|余承东|鸿蒙|海思|昇腾|HUAWEI|HarmonyOS|HiSilicon/i, '华为'],
  [/苹果|iPhone|iOS|Mac|库克|Apple/i, '苹果'],
  [/人工智能|大模型|ChatGPT|OpenAI|Claude|Gemini|\bAI\b|LLM/i, '人工智能'],
  [/特斯拉|Model [3YXS]|马斯克|Tesla/i, '特斯拉'],
  [/粤语|广府话|广东话|广州话/i, '粤语'],
  [/英语|English|英文|雅思|托福|口语|翻译|双语/i, '英语'],
];
// ↑↑↑ 规则表结束 ↑↑↑

const 标题 = String(src['标题'] || '');

const 标签组 = [];
for (const [词, 名] of 标签规则) {
  const g = new RegExp(词.source, 'gi');
  if (g.test(标题) && !标签组.includes(名)) 标签组.push(名);
}

return { json: { ...src, 标签: 标签组.join('/') || '未分类' } };

// ===== 批量分组：每 30 条打成一批，只带 id + 标题 =====
// 输出每条是一个批次：{ batchNo, ids: [...], json: '给 AI 的文本' }
const items = $input.all();
const 每批 = 30;

const 批次 = [];
for (let i = 0; i < items.length; i += 每批) {
  const 片 = items.slice(i, i + 每批).map((it, k) => ({
    id: i + k,
    标题: String(it.json['标题'] || '').replace(/\s+/g, ' ').trim(),
  }));
  批次.push({
    json: {
      batchNo: 批次.length + 1,
      ids: 片.map(p => p.id),
      json: 片.map(p => `${p.id}｜${p.标题}`).join('\n'),
    },
  });
}

return 批次;

// ===== 套用 AI 分类结果 =====
// 输入：AI批量分类（成功那一路）
// AI 只回 id + 分类 + 标签；这里用 id 找回原条目，补回全部字段。
const 全部 = $('打标签').all().map(i => i.json);

function 取数组(对象) {
  if (!对象 || typeof 对象 !== 'object') return [];
  for (const 键 of ['items', '结果', 'results', 'list']) {
    if (Array.isArray(对象[键])) return 对象[键];
  }
  return [];
}

const 分类表 = {};
const 待观察 = [];

for (const it of $input.all()) {
  let 数据 = it.json;
  if (typeof 数据 === 'string') {
    try { 数据 = JSON.parse(数据); } catch (e) { continue; }
  }
  if (数据 && typeof 数据.text === 'string') {
    try { 数据 = JSON.parse(数据.text); } catch (e) { /* 保持原样 */ }
  }
  const 结果 = 取数组(数据);
  for (const r of 结果) {
    const id = Number(r.id ?? r.ID ?? r.ID号);
    if (!isFinite(id) || !全部[id]) continue;
    let 分类 = String(r.分类 ?? r.level ?? r.L ?? '').toUpperCase().replace(/^([LAGX])[0-9]*$/, '$1');
    if (!['L', 'A', 'G', 'X', 'L1', 'L2', 'L3'].includes(分类)) 分类 = 'G';
    let 标签 = r.标签 ?? r.tag ?? r.tags ?? '';
    if (Array.isArray(标签)) 标签 = 标签.join('/');
    分类表[id] = { 分类, 标签: String(标签 || '') };

    // 语言类要再分 L1 / L2 / L3
    if (分类 === 'L') {
      const 级 = String(r.level ?? r.级别 ?? r.L ?? '').toUpperCase().match(/L([123])/);
      const 建议 = String(r.建议 ?? r.advice ?? '').toLowerCase();
      if (级) 分类表[id].分类 = 'L' + 级[1];
      else if (建议 === 'l3') 分类表[id].分类 = 'L3';
      else 分类表[id].分类 = 'L1';
    }
  }
}

const 输出 = [];

全部.forEach((n, id) => {
  const 判 = 分类表[id];
  if (!判) return;   
  // AI 没判断的不冒充 G
  const 分类 = 判.分类;
  const 标签 = (判 && 判.标签 ? 判.标签 : (n['标签'] || ''));

  // X：多资讯合集 / 早报晚报汇总 / 明显广告 → 直接丢弃
  if (分类 === 'X') return;

  const 新 = { ...n, 分类, 标签 };

  // L3：不抓全文，只留标题进「待观察」
  if (分类 === 'L3') {
    待观察.push({ id, 标题: n['标题'], 链接: n['链接'], 来源: n['来源'], 日期: n['日期'], 标签 });
  }

  输出.push({ json: 新 });
});

// 把待观察清单交给占位接口保存（先不接飞书表格）
if (待观察.length > 0) {
  try { $getWorkflowStaticData('global').待观察 = 待观察; } catch (e) { /* 忽略 */ }
}

return 输出;

// ===== 三分类排序 =====
// 把 AI 返回的 L1/L2/L3/A/G 归到三个频道；优先级：语言 > AI > 全网热点
// 辅助标签转回中文
const items = $input.all();

const 标签英文转中文 = {
  DeepSeek: 'DeepSeek',
  Huawei: '华为',
  华为: '华为',
  Apple: '苹果',
  苹果: '苹果',
  AI: '人工智能',
  人工智能: '人工智能',
  Tesla: '特斯拉',
  特斯拉: '特斯拉',
  Cantonese: '粤语',
  粤语: '粤语',
  English: '英语',
  英语: '英语',
};

function 频道(分类) {
  if (分类 === 'L1' || 分类 === 'L2' || 分类 === 'L3') return '语言资讯';
  if (分类 === 'A') return 'AI资讯';
  return '全网热点资讯';
}

const 顺序 = ['语言资讯', 'AI资讯', '全网热点资讯'];
const 每频道序号 = {};
const 结果 = [];

for (const it of items) {
  const n = { ...it.json };
  const 分类 = String(n['分类'] || 'G').toUpperCase();
  n['分类'] = 频道(分类);
  n['级别'] = 分类;

  // 英文标签转中文，去重
  const 标签组 = String(n['标签'] || '')
    .split('/')
    .map(t => t.trim())
    .filter(Boolean)
    .map(t => 标签英文转中文[t] || t);
  n['标签'] = [...new Set(标签组)].join('/') || '未分类';

  // 板块：沿用来源维度（新闻媒体 / 大厂动态 / 视频 / 社交媒体）
  每频道序号[n['分类']] = (每频道序号[n['分类']] || 0) + 1;
  n['_序'] = 每频道序号[n['分类']];

  结果.push({ json: n });
}

return 结果;

// ===== 挑出语言资讯（L1 / L2 才抓全文）=====
// L3 已在上一节点记进「待观察」，这里只放行 L1 / L2
// 凡是能进到本节点的，分类都是「语言资讯」
const items = $input.all();

const 抓 = items
  .filter(it => {
    const 级 = String(it.json['级别'] || '');
    return 级 === 'L1' || 级 === 'L2';
  })
  .map(it => ({ json: it.json }));

return 抓;

// ===== 清洗网页正文 =====
// 抓不到 / 截断时，退回 RSS 摘要（保底，保证这条资讯还会推送）
const 原文 = $('挑出语言资讯').item.json;
const r = $json;

let 正文 = '';
try {
  const 原始 = typeof r === 'string' ? r : (r && (r.data || r.body || r.text)) || '';
  正文 = String(原始)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&[a-z]+;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
} catch (e) {
  正文 = '';
}

// 抓不到有效正文（少于 150 字）就用 RSS 摘要兜底
if (正文.length < 150) {
  正文 = String(原文['内容'] || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

// 最多 3000 字，控制 AI 消耗
if (正文.length > 3000) 正文 = 正文.slice(0, 3000) + '…';

return { json: { ...原文, 正文 } };

// ===== 程序整理：AI 资讯 + 全网热点 =====
// 这两类不用 AI 改写，只由程序保留标题、截断摘要、统一字段
const 分类顺序 = ['语言资讯', 'AI资讯', '全网热点资讯'];

const items = $input.all().map(i => i.json);

function 洗(t) {
  return String(t || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&[a-z]+;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function 截(t, n) {
  const s = 洗(t);
  return s.length > n ? s.slice(0, n) + '…' : s;
}

const 输出 = [];

for (const n of items) {
  const 分类 = String(n['分类'] || '');
  if (!分类顺序.includes(分类)) continue;

  const 标题 = 洗(n['标题']);
  if (!标题) continue;

  const 条 = {
    标题,
    内容: 截(n['内容'] || n['正文'] || '', 140),
    日期: n['日期'] || new Date().toISOString(),
    链接: String(n['链接'] || '').trim(),
    来源: n['来源'] || '未知来源',
    板块: n['板块'] || '新闻媒体',
    分类,
    标签: n['标签'] || '未分类',
    级别: n['级别'] || '',
  };

  // 语言线把深度解析结果一并带上
  if (分类 === '语言资讯') {
    条['核心观点'] = String(n['核心观点'] || '');
    条['语言话题'] = String(n['语言话题'] || '');
    条['值得关注'] = String(n['值得关注'] || '');
    条['原文摘要'] = String(n['原文摘要'] || '');
    条['待观察'] = !!n['待观察'];
  }

  输出.push({ json: 条 });
}

return 输出;

// ===== 查重 =====
// 规则（沿用老规矩）：链接 或 标题 任一命中即算已发过
// 记录只保留 7 天，更早的不参与比对
const 资讯 = $('程序整理AI与热点').all().map(i => i.json);

let 旧记录 = [];
try { 旧记录 = $('读取已推送记录').all().map(i => i.json); } catch (e) { 旧记录 = []; }

const 七天前 = Date.now() - 7 * 24 * 60 * 60 * 1000;

const 有效旧记录 = 旧记录.filter(r => {
  const t = r.pushed_at ? new Date(r.pushed_at).getTime() : 0;
  return t >= 七天前;
});

const 已发链接 = new Set(有效旧记录.map(r => String(r.link || '').trim()).filter(Boolean));
const 已发标题 = new Set(有效旧记录.map(r => String(r.title || '').trim()).filter(Boolean));

const 新的 = 资讯.filter(n => {
  const link = String(n['链接'] || '').trim();
  const title = String(n['标题'] || '').trim();
  if (link && 已发链接.has(link)) return false;
  if (title && 已发标题.has(title)) return false;
  return true;
});

return 新的.map(n => ({ json: n }));

// ===== 最终排序 =====
// 频道顺序：语言资讯 → AI资讯 → 全网热点资讯
const items = $input.all();

const sectionOrder = ['语言资讯', 'AI资讯', '全网热点资讯'];

items.sort((a, b) => {
  const ia = sectionOrder.indexOf(a.json['分类'] || '');
  const ib = sectionOrder.indexOf(b.json['分类'] || '');
  return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib);
});

return items;

// ===== 全网热点小报 =====
const items = $input.all().map(i => i.json);

const list = items.filter(n => n['分类'] === '全网热点资讯');

function fmtTime(v) {
  if (!v) return '';
  const d = new Date(v);
  if (isNaN(d.getTime())) return '';
  const p = x => String(x).padStart(2, '0');
  return `${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
}

function cut(t, n) {
  const s = String(t || '').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + '…' : s;
}

const 板块顺序 = ['新闻媒体', '大厂动态', '视频', '社交媒体'];

let md = `# ${$now.toFormat('yyyy-MM-dd')} 全网热点小报\n`;

if (list.length === 0) {
  md += '\n今天没有可推送的资讯。\n';
}

const 板块集 = [...new Set(list.map(n => n['板块'] || '新闻媒体'))];
板块集.sort((a, b) => {
  const ia = 板块顺序.indexOf(a), ib = 板块顺序.indexOf(b);
  return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib);
});

for (const 板块 of 板块集) {
  const 组 = list.filter(n => (n['板块'] || '新闻媒体') === 板块);
  md += `\n## ${板块}\n\n`;
  for (const n of 组) {
    md += `【${板块}】 〔${n['标签'] || '未分类'}〕 《${n['来源'] || ''}》 ${fmtTime(n['日期'])}\n`;
    md += `${n['标题'] || ''}\n`;
    const c = cut(n['内容'], 120);
    if (c && c !== n['标题']) md += `${c}\n`;
    md += `${n['链接'] || ''}\n\n`;
  }
}

return [{ json: { markdown: md } }];

// ===== AI资讯小报 =====
const items = $input.all().map(i => i.json);

const list = items.filter(n => n['分类'] === 'AI资讯');

function fmtTime(v) {
  if (!v) return '';
  const d = new Date(v);
  if (isNaN(d.getTime())) return '';
  const p = x => String(x).padStart(2, '0');
  return `${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
}

function cut(t, n) {
  const s = String(t || '').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + '…' : s;
}

const 板块顺序 = ['大厂动态', '新闻媒体', '视频', '社交媒体'];

let md = `# ${$now.toFormat('yyyy-MM-dd')} AI资讯小报\n`;

if (list.length === 0) {
  md += '\n今天没有可推送的资讯。\n';
}

const 板块集 = [...new Set(list.map(n => n['板块'] || '新闻媒体'))];
板块集.sort((a, b) => {
  const ia = 板块顺序.indexOf(a), ib = 板块顺序.indexOf(b);
  return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib);
});

for (const 板块 of 板块集) {
  const 组 = list.filter(n => (n['板块'] || '新闻媒体') === 板块);
  md += `\n## ${板块}\n\n`;
  for (const n of 组) {
    md += `【${板块}】 〔${n['标签'] || '未分类'}〕 《${n['来源'] || ''}》 ${fmtTime(n['日期'])}\n`;
    md += `${n['标题'] || ''}\n`;
    const c = cut(n['内容'], 120);
    if (c && c !== n['标题']) md += `${c}\n`;
    md += `${n['链接'] || ''}\n\n`;
  }
}

return [{ json: { markdown: md } }];

// ===== 语言资讯小报 =====
// L1 / L2 带深度解析；L3 单独列进「待观察」，只有标题和链接
const items = $input.all().map(i => i.json);

const 全部 = items.filter(n => n['分类'] === '语言资讯');
const 主列 = 全部.filter(n => n['级别'] !== 'L3');
const 待观察 = 全部.filter(n => n['级别'] === 'L3');

function fmtTime(v) {
  if (!v) return '';
  const d = new Date(v);
  if (isNaN(d.getTime())) return '';
  const p = x => String(x).padStart(2, '0');
  return `${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
}

function cut(t, n) {
  const s = String(t || '').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + '…' : s;
}

let md = `# ${$now.toFormat('yyyy-MM-dd')} 语言资讯小报\n`;

if (全部.length === 0) {
  md += '\n今天没有可推送的资讯。\n';
}

for (const n of 主列) {
  md += `\n## ${n['板块'] || '新闻媒体'}\n\n`;
  md += `【${n['板块'] || '新闻媒体'}】 〔${n['标签'] || '未分类'}〕 《${n['来源'] || ''}》 ${fmtTime(n['日期'])}\n`;
  md += `${n['标题'] || ''}\n`;
  if (n['核心观点']) md += `核心观点：${cut(n['核心观点'], 120)}\n`;
  if (n['语言话题']) md += `语言话题：${cut(n['语言话题'], 120)}\n`;
  if (n['值得关注']) md += `值得关注：${cut(n['值得关注'], 160)}\n`;
  const 摘要 = cut(n['原文摘要'] || n['内容'], 120);
  if (摘要 && 摘要 !== n['标题']) md += `${摘要}\n`;
  md += `${n['链接'] || ''}\n\n`;
}

if (待观察.length > 0) {
  md += '\n## 待观察\n\n';
  for (const n of 待观察) {
    md += `〔${n['标签'] || '未分类'}〕 《${n['来源'] || ''}》 ${fmtTime(n['日期'])}\n`;
if (n['中文标题']) {
  md += `${n['中文标题']}\n`;
  md += `> ${n['标题'] || ''}\n`;
} else {
  md += `${n['标题'] || ''}\n`;
}
    md += `${n['链接'] || ''}\n\n`;
  }
}

return [{ json: { markdown: md } }];

// 把深度解析的 4 个字段按 id 并回原条目
const 原文 = $('挑出语言资讯').item.json;   // 与当前条目配对的原条目

let 数据 = $json;
if (typeof 数据 === 'string') { try { 数据 = JSON.parse(数据); } catch (e) {} }
