// 抓取全文成功后，把网页正文清洗出来，同时保留原条目字段
const 原文 = $('挑出语言资讯').item.json;   // 原条目（含标题/来源/链接）

let 原始 = '';
try {
  const r = $json;
  原始 = typeof r === 'string' ? r : (r && (r.data || r.body || r.text)) || '';
} catch (e) { 原始 = ''; }

let 正文 = String(原始)
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&[a-z]+;/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// 抓不到有效正文（少于 150 字）就用 RSS 摘要兜底
if (正文.length < 150) {
  正文 = String(原文['内容'] || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

// 最多 3000 字
if (正文.length > 3000) 正文 = 正文.slice(0, 3000) + '…';

return { json: { ...原文, 正文 } };

